import ctypes,json,os,pathlib,re,shlex,subprocess,sys,time
config=json.loads(pathlib.Path('config.json').read_text())
children={};observed={};labels={os.getpid():'supervisor'}
if config.get('parent_case'):
 assert ctypes.CDLL(None).prctl(15,b'pd-parent',0,0,0)==0
def invoke(arguments):
 args=[s.format(**{k:p.pid for k,p in children.items()}) for s in arguments]
 script='pidof '+shlex.join(args)+'; rc=$?; exit "$rc"'
 side=subprocess.Popen(['pd-parent' if config.get('parent_case') else sys.argv[1],'--noprofile','--norc','-c',script],executable=sys.argv[1],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 labels[side.pid]='caller'
 try:out,err=side.communicate(timeout=4)
 except BaseException:side.kill();side.wait();raise
 def replace(match):
  pid=int(match[0]);assert pid in labels,('unowned pid result',pid,out)
  return labels[pid].encode()
 normalized=re.sub(rb'[0-9]+',replace,out)
 # Diagnostics retain exact text except the known invoking-shell path.
 diagnostic=err.decode().replace(sys.argv[1],'$SHELL')
 return {'status':side.returncode,'stdout':normalized.decode(),'stderr':diagnostic}
try:
 for item in config['children']:
  label=item['label'];env=dict(os.environ,FIXTURE_COMM=item['comm'],FIXTURE_READY='ready-'+label)
  argv=['./fixture-script-long-name'];executable='./fixture-script-long-name'
  p=subprocess.Popen(argv,executable=executable,env=env,stdin=subprocess.PIPE,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE)
  children[label]=p;labels[p.pid]=label
 deadline=time.monotonic()+3
 for item in config['children']:
  label=item['label'];p=children[label]
  while not pathlib.Path('ready-'+label).exists():
   if p.poll() is not None:raise RuntimeError(('holder exited',label,p.returncode,p.stderr.read()))
   if time.monotonic()>deadline:raise RuntimeError('holder readiness deadline')
   time.sleep(.01)
  comm=pathlib.Path('/proc/%d/comm'%p.pid).read_text().rstrip('\n')
  argv=pathlib.Path('/proc/%d/cmdline'%p.pid).read_bytes().rstrip(b'\0').split(b'\0')
  assert comm==item['comm'] and argv==[s.encode() for s in item['argv']],(comm,argv,item)
  observed[label]={'comm':comm,'argv':item['argv']}
 if config.get('parent_case'):
  control=invoke(['pd-parent'])
  assert 'caller' in control['stdout'],control
  print('control='+json.dumps(control,sort_keys=True))
 print('result='+json.dumps(invoke(config['arguments']),sort_keys=True))
 pathlib.Path('process-records.json').write_text(json.dumps(observed,sort_keys=True)+'\n')
finally:
 for p in children.values():
  if p.poll() is None:p.terminate()
 for p in children.values():
  try:p.wait(timeout=2)
  except subprocess.TimeoutExpired:p.kill();p.wait()
  p.stderr.close()
  p.stdin.close()

